@if($audioCampaign)<section class="settings-panel" aria-label="Publicidade em áudio"><p class="eyebrow">Patrocinado</p><strong>{{ $audioCampaign->spot->advertiser ?: $audioCampaign->name }}</strong><audio controls preload="none" src="{{ $audioCampaign->spot->audioUrl() }}" data-audio-ad data-track-url="{{ route('audio-ads.play',$audioCampaign) }}"></audio></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const a=document.querySelector('[data-audio-ad]');if(!a)return;let sent=false;a.addEventListener('play',()=>{if(sent)return;sent=true;fetch(a.dataset.trackUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({listened_seconds:0})})});});</script>@endif
